  const cs = () => sq.prepare('SELECT cases FROM master_list WHERE id=97001').get().cases;
  const plog = () => sq.prepare("SELECT * FROM part_price_log WHERE parent='70-7-7' ORDER BY id").all();
  const all0 = shelf();
