// Owner (2026-10-08): "every day at 8:50 pm we need a scan form — today none was made (what we printed 5:30–8:50 pm is on no form)".
// The 30-min server timer can't hit 8:50 (no form after 9 pm) → an exact alarm (Durable Object) wakes the server at each time.
console.log('\n⏰ Scan form clock: exact alarm at 8:50 pm every day (+ night check), set again after each one');
{
  const { readFileSync: rf16 } = await import('node:fs');
  const ws = rf16(workerPath, 'utf8'), wt = rf16(fileURLToPath(new URL('../wrangler.toml', import.meta.url)), 'utf8');
  const mod = await import(workerPath);
  const cfg = { scanFormOn: true, scanFormTimes: 'Mon-Fri 16:30, 20:50; Sat 13:45, 20:50; Sun 20:50', scanFormCheckAt: '20:55' };
  const grab = n => (ws.match(new RegExp('function ' + n + '\\([\\s\\S]*?\\n}')) || [''])[0];
  const f = new Function("const AUTOLABEL_DAYS = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];" + ['autolabelNyNow', 'autolabelTimesParse', 'sfNyToUtc', 'autolabelNextScanFormAt'].map(grab).join('\n') + '; return autolabelNextScanFormAt;')();
  const nx = t => new Date(f(cfg, new Date(t))).toISOString();
  // New York = UTC − 4 (October). Wed Oct 7 6:00 pm → 8:50 pm (00:50Z) +20 s; 8:51 pm → night check 8:55 pm; 8:56 pm → Thu 4:30 pm.
  check('Wed 6:00 pm → next alarm 8:50 pm; 8:51 pm → night check 8:55 pm; 8:56 pm → Thu 4:30 pm (all + 20 s)',
    nx('2026-10-07T22:00:00Z') === '2026-10-08T00:50:20.000Z' && nx('2026-10-08T00:51:00Z') === '2026-10-08T00:55:20.000Z' && nx('2026-10-08T00:56:00Z') === '2026-10-08T20:30:20.000Z', [nx('2026-10-07T22:00:00Z'), nx('2026-10-08T00:51:00Z'), nx('2026-10-08T00:56:00Z')]);
  check('…Saturday after 1:45 pm → Saturday 8:50 pm too; winter time (EST, UTC − 5): Mon Dec 7 8:50 pm = 01:50Z',
    nx('2026-10-10T18:00:00Z') === '2026-10-11T00:50:20.000Z' && nx('2026-12-07T23:00:00Z') === '2026-12-08T01:50:20.000Z', [nx('2026-10-10T18:00:00Z'), nx('2026-12-07T23:00:00Z')]);
  // The alarm itself: makes the slot's form through the normal tick, then sets the next alarm.
  let alarmAt = null; const store = { getAlarm: async () => alarmAt, setAlarm: async t => { alarmAt = t; }, deleteAlarm: async () => { alarmAt = null; } };
  const clock = new mod.ScanFormClock({ storage: store }, env);
  const r = await (await clock.fetch(new Request('https://sf-clock/ensure'))).json();
  check('ScanFormClock sets its alarm to the next scan form time (exported for Cloudflare, bound as SF_CLOCK in wrangler.toml)',
    r.ok && typeof alarmAt === 'number' && alarmAt > Date.now() && /\[\[durable_objects\.bindings\]\]\s*name = "SF_CLOCK"\s*class_name = "ScanFormClock"/.test(wt) && /new_sqlite_classes = \["ScanFormClock"\]/.test(wt), [r, alarmAt]);
  check('…the 30-min timer and every settings save make sure the alarm is set; the scan form list shows the next time', /async function autolabelCron\(env\) \{\n  const cfg = await autolabelLoadConfig\(env\);\n  await scanFormClockEnsure\(env\);/.test(ws) && /nextForm: \(\(\) =>/.test(ws), null);
}

// Owner (2026-10-08): "Inventory → Transfer: every scan is a little slow, we wait for the next thing to show up". The lookup now
// reads only the item's SKU Mgr rows (not all of them) and keeps the UPC sheet 60 s — the answer must be exactly the same.
console.log('\nTransfer scan lookup: faster, same answer (rows, order, row numbers)');
{
  sq.exec(`INSERT INTO master_list (base_sku, sku, name, part_num, location, cases, units_per_case) VALUES
    ('216-1-1','216-1-1','Tee 216','216-1-1=10','C1=6-1-1',3,100), ('216-1-11','216-1-11','Other','216-1-11=10','C1=6-1-2',2,100),
    ('216-1-1C','216-1-1C','Tee 216 C','216-1-1C=5','C2=6-1-1',4,50), ('999-9-9','999-9-9','Far','999-9-9=1','C1=6-1-3',1,1),
    ('216-1-1','216-1-1','Tee 216','216-1-1=25','C3=6-1-1',6,250)`);
  const all = sq.prepare('SELECT id, part_num, location FROM master_list').all(); // the full list, in its own order (old way)
  const idx = id => all.findIndex(r => r.id === id) + 2; // old rowIndex = position in the full list + 1 (row 1 = header)
  const d = await get('/inventory/lookup?code=216-1-1');
  const want = all.filter(r => /^216-1-1(C)?=/.test(r.part_num)).map(r => r.part_num + '@' + r.location + '#' + idx(r.id));
  const got = (d.locations || []).map(l => l.partNum + '@' + l.location + '#' + l.rowIndex);
  check('216-1-1: its =10, =25 and the C part # =5 (same parent), not 216-1-11 or others; same order and row numbers as reading every row',
    JSON.stringify(got) === JSON.stringify(want) && d.isMultiVariant === true && d.name === 'Tee 216' && got.length === 3, { got, want });
  const one = await get('/inventory/lookup?code=216-1-25'.replace('216-1-25', '216-1-1=25'));
  check('…an exact part # scan (216-1-1=25) still lists the whole family the same way', (one.locations || []).length === 3 && one.partNum === '216-1-1=25', one.locations);
  sq.exec("DELETE FROM master_list WHERE base_sku IN ('216-1-1','216-1-11','216-1-1C','999-9-9')");
}

// Owner: "every html, every tab I can let which level see, and right next to the check box I can put only who can
// see — just add their user name — even if they are Worker level they can still see it; and under a tab, the
// separate parts need a check box too".
console.log('\nAdmin → Pages & Tabs: every page, tab and part per level + "👤 Also these people" by user name');
{
  const { readFileSync } = await import('node:fs');
  const xa = readFileSync(fileURLToPath(new URL('../xf-access.js', import.meta.url)), 'utf8');
  const ad = readFileSync(fileURLToPath(new URL('../xfitting-admin.html', import.meta.url)), 'utf8');
  // catalog: load it the way a page does (a fake window), check every key
  const catSrc = xa.slice(xa.indexOf('  var card = function'), xa.indexOf('  window.XF_ACCESS_CATALOG = CATALOG;'));
  const win = {}; new Function('window', catSrc + 'window.XF_ACCESS_CATALOG = CATALOG;')(win);
  const cat = win.XF_ACCESS_CATALOG || [];
  const keys = []; const KEY = /^[a-z0-9_-]{1,40}(:[a-z0-9_-]{1,40}){0,2}$/;
  for (const p of cat) {
    keys.push(p.key);
    for (const x of p.parts || []) keys.push(p.key + ':' + x.key);
    for (const t of p.tabs || []) { keys.push(p.key + ':' + t.key); for (const x of t.parts || []) keys.push(p.key + ':' + t.key + ':' + x.key); }
  }
  const partN = keys.filter(k => k.split(':').length === 3).length + cat.reduce((n, p) => n + (p.parts || []).length, 0);
  check('the list has every page (' + cat.length + '), every tab, and parts under tabs (' + partN + ' parts); every key unique and one the server accepts', cat.length >= 15 && partN >= 20 && new Set(keys).size === keys.length && keys.every(k => KEY.test(k)) && keys.length <= 2000,
    { pages: cat.length, partN, dup: keys.filter((k, i) => keys.indexOf(k) !== i), bad: keys.filter(k => !KEY.test(k)) });
  check('every part has a selector so it can be hidden; pages and tabs are hidden by a style rule the moment they draw', cat.every(p => (p.parts || []).concat(...(p.tabs || []).map(t => t.parts || [])).every(x => x.sel && x.label)) && /xf-access-parts/.test(xa) && /display:none!important/.test(xa), null);
  check('Admin page: a part row under each tab, and the "👤 Also these people" name box next to the check boxes', /ad-pg-xrow/.test(ad) && /ad-pg-names/.test(ad) && /function adPgNamesPlan/.test(ad) && /ad-pg-userlist/.test(ad), null);

  // a Worker-level person named on a part (and its tab + page), while the Worker level has them hidden
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const km = await crypto.subtle.importKey('raw', new TextEncoder().encode('named1pass'), 'PBKDF2', false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits({ name: 'PBKDF2', salt, iterations: 100000, hash: 'SHA-256' }, km, 256);
  const nu = sq.prepare("INSERT INTO cred_users (username, password_hash, display_name, active, created_at, level) VALUES (?,?,?,1,?,'worker')").run('named1', hex(salt) + ':' + hex(new Uint8Array(bits)), 'Named One', new Date().toISOString());
  const nid = Number(nu.lastInsertRowid);
  const lg = await (await call('/auth/login', { method: 'POST', body: JSON.stringify({ username: 'named1', password: 'named1pass' }) })).json();
  const blockedFor = async () => ((await (await call('/auth/access', { headers: { 'X-Cred-Token': lg.token } })).json()).blocked) || [];
  const lv0 = sq.prepare("SELECT item, allow FROM access_rules WHERE scope = 'level:worker'").all();
  const sv = await post('/admin/access/save', { scope: 'level:worker', rules: { reorder: 0, 'reorder:reorder': 0, 'reorder:reorder:csv': 0, 'inventory:history:report': 0 } });
  const b1 = await blockedFor();
  check('Worker level: a page, a tab and a part (3-level key page:tab:part) can be hidden — saved and hidden for a Worker', sv.ok && sv.saved === 4 && ['reorder', 'reorder:reorder', 'reorder:reorder:csv', 'inventory:history:report'].every(k => b1.includes(k)), { sv, b1 });
  const sn = await post('/admin/access/save', { scope: 'user:' + nid, rules: { reorder: 1, 'reorder:reorder': 1, 'reorder:reorder:csv': 1 } });
  const b2 = await blockedFor();
  check('…name "named1" typed next to Reorder → CSV: they see it (and the tab + page it is on) though Worker level is hidden; everything else stays hidden', sn.ok && !b2.includes('reorder') && !b2.includes('reorder:reorder') && !b2.includes('reorder:reorder:csv') && b2.includes('inventory:history:report'), { sn, b2 });
  const other = await post('/admin/access/save', { scope: 'user:' + nid, rules: { 'reorder:reorder:bogus key': 1, 'a:b:c:d': 1 } });
  check('…keys the server can\'t read are not saved', other.ok && other.saved === 0, other);
  // put it back
  await post('/admin/access/save', { scope: 'user:' + nid, rules: {} });
  await post('/admin/access/save', { scope: 'level:worker', rules: Object.fromEntries(lv0.map(r => [r.item, r.allow])) });
}

// Owner (2026-10-08): "Print Log — show it was from AUTO PRINT; any auto-printed label the scanner did not pick up,
// give us the report to check later, and keep track of Picking and Packing too (maybe scanned later, our scanner just
// never picked it up)".
console.log('\n🤖 Print Log: AUTO PRINT tag; report of auto prints not read by the Print Log scanner (+ Picking / Packing)');
{
  await get('/veeqo/autolabel/config'); // label tables
  const ins = (n, t) => sq.prepare("INSERT INTO label_print_queue (order_number, channel, tracking, carrier, service, created_at) VALUES (?, 'eBay', ?, 'USPS', 'GA', ?)").run(n, t, new Date().toISOString()).lastInsertRowid;
  const T = ['9400100000000000000901', '9400100000000000000902', '9400100000000000000903', '9400100000000000000904'];
  const ids = T.map((t, i) => Number(ins('AP-' + (i + 1), t)));
  // "Today" starts at midnight New York time: never stamp the prints before it (right after midnight "30 min ago" was
  // yesterday and the report — correctly — left them out; 2026-10-10 00:29).
  const nyN = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/New_York' })), sinceMid = nyN.getHours() * 60 + nyN.getMinutes();
  const ago = m => new Date(Date.now() - Math.min(m, Math.max(0, sinceMid - 1)) * 60000).toISOString();
  sq.prepare("INSERT INTO label_print_batch (ts, day, by_user, source, count, label_ids) VALUES (?, ?, 'station', 'printer station', 3, ?)").run(ago(30), new Date().toISOString().slice(0, 10), JSON.stringify(ids.slice(0, 3)));
  sq.prepare("INSERT INTO label_print_batch (ts, day, by_user, source, count, label_ids) VALUES (?, ?, 'KL', 'by hand', 1, ?)").run(ago(30), new Date().toISOString().slice(0, 10), JSON.stringify([ids[3]]));
  await post('/ship/print-log', { tracking: T[0] });               // AP-1 read by the Print Log scanner
  await post('/ship/print-log', { tracking: T[3] });               // AP-4 printed by hand (not auto)
  await post('/ship/pick', { tracking: T[1], initials: 'PK' });    // AP-2 missed by Print Log, picked later
  await post('/ship/scan', { tracking: T[1], initials: 'PA' });    // …and packed
  const pl = await get('/ship/print-log');
  const S = t => (pl.scans || []).find(x => String(x.tracking).toUpperCase() === t) || {};
  check('Print Log: the station\'s own print shows 🤖 AUTO PRINT (with its order #); a label printed by hand does not',
    S(T[0]).autoPrint === true && S(T[0]).order === 'AP-1' && !S(T[3]).autoPrint, [S(T[0]), S(T[3])]);
  const rp = await get('/ship/auto-print-report?days=1');
  const R = n => (rp.rows || []).find(x => x.order === n) || {};
  check('report: AP-1 ✓ read by Print Log · AP-2 ⚠ missed by Print Log but picked (PK) + packed (PA) · AP-3 ❌ not scanned anywhere · AP-4 (by hand) not in it',
    rp.ok && R('AP-1').state === 'read' && R('AP-2').state === 'later' && R('AP-2').pickBy === 'PK' && R('AP-2').packBy === 'PA' && !!R('AP-2').pickAt && !!R('AP-2').packAt
    && R('AP-3').state === 'missing' && !R('AP-4').order && rp.counts.total === 3 && rp.counts.later === 1 && rp.counts.missing === 1 && rp.counts.read === 1, rp);
  const { readFileSync: rf13 } = await import('node:fs');
  const ph = rf13(fileURLToPath(new URL('../packship.html', import.meta.url)), 'utf8');
  check('Print Log tab: 🤖 AUTO PRINT badge, the 🤖 Auto print report card (Today / 3 / 7 / 30 days, not read / not scanned / all, Excel)',
    /s\.autoPrint \? '<span class="ps-badge"/.test(ph) && /id="ps-ap-card"/.test(ph) && /\/ship\/auto-print-report\?days=/.test(ph) && /window\.psApCsv = function/.test(ph), null);
}

