// Owner (2026-10-09): Pack & Ship Picking / Packing — the scanner reads both the QR code and the barcode on one label, so
// the same order came in twice and the "Duplicate" popup went off. The same tracking again within 5 s is ignored quietly;
// after 5 s the normal duplicate check (popup) still runs.
console.log('\n📦 Pack & Ship: same label read twice within 5 s (QR + barcode) is ignored, no Duplicate popup');
{
  const { readFileSync } = await import('node:fs');
  const ph = readFileSync(fileURLToPath(new URL('../packship.html', import.meta.url)), 'utf8');
  const src = (ph.match(/var PS_SAME_SCAN_IGNORE_MS = 5000;[\s\S]*?function _psQuickRepeat\(kind, tracking\) \{[\s\S]*?\n\}/) || [''])[0];
  let now = 1000000; const realNow = Date.now; Date.now = () => now;
  let r = [];
  try {
    const q = new Function(src + '; return _psQuickRepeat;')();
    r.push(q('pick', '1ZABC'));           // first read → handled
    now += 300;  r.push(q('pick', '1ZABC'));  // QR read 0.3 s later → ignored
    r.push(q('pack', '1ZABC'));           // Packing tab keeps its own record → handled
    now += 2000; r.push(q('pick', '9400111'));  // a different label → handled
    now += 6000; r.push(q('pick', '9400111'));  // same label 6 s later → normal duplicate check
  } finally { Date.now = realNow; }
  check('first read handled, QR re-read 0.3 s later ignored, other tab / other label handled, same label after 5 s goes to the duplicate check',
    JSON.stringify(r) === JSON.stringify([false, true, false, false, false]), r);
  const pk1 = ph.indexOf("if (_psQuickRepeat('pack', tracking)) { inp.focus(); return; }"), pkDup = ph.indexOf('psDupeShowAlert(tracking, dupe.timestamp');
  const pi1 = ph.indexOf("if (_psQuickRepeat('pick', tracking)) { inp.focus(); return; }"), piDup = ph.indexOf('psPickDupeShowAlert(tracking, dupe.timestamp');
  check('…checked in Packing and Picking before the Duplicate / Already Picked popup', pk1 > 0 && pk1 < pkDup && pi1 > 0 && pi1 < piDup, { pk1, pkDup, pi1, piDup });
}

// Owner (2026-10-10): 🚢 Container here — before starting a pallet, confirm starting, say if it's opened, and confirm
// the boxes on it (our record → ✅ Correct, or ✏️ type what is there). Kept for History, so an extra / short box shows
// whether it was already that way at the start. The normal steps after it don't change; inventory never changes.
console.log('\n🧮 Container here: box count confirmed before starting a pallet');
{
  const { readFileSync } = await import('node:fs');
  const ih = readFileSync(fileURLToPath(new URL('../inventory.html', import.meta.url)), 'utf8');
  const ts = new Date().toISOString();
  sq.prepare("INSERT INTO reorder_pallet (title, vendor, pallet, part, description, cases, pcs, pcs_per_ctn, updated_at) VALUES ('CNT CT','KW','3','CN-1=10X','valve',6,60,10,?), ('CNT CT','KW','3','CN-2=5','tee',3,15,5,?)").run(ts, ts);
  const ml0 = JSON.stringify(sq.prepare('SELECT SUM(cases) c FROM master_list').get()), lg0 = sq.prepare('SELECT COUNT(*) n FROM inventory_log').get().n;
  const pv0 = await get('/inventory/containers/pallet-view?title=' + encodeURIComponent('CNT CT') + '&vendor=KW&pallet=3');
  const body = { title: 'CNT CT', vendor: 'KW', pallet: '3', opened: true, expected: 9, counted: 8, how: '2×3+2', _requestId: 'cnt-test-1' };
  const c1 = await post('/inventory/containers/pallet-count', body), c2 = await post('/inventory/containers/pallet-count', body); // sent twice (phone outbox)
  const bad = await post('/inventory/containers/pallet-count', { title: 'CNT CT', vendor: 'KW', pallet: '3', expected: 9 });
  const pv1 = await get('/inventory/containers/pallet-view?title=' + encodeURIComponent('CNT CT') + '&vendor=KW&pallet=3');
  const det = await get('/inventory/containers/pallet-detail?title=' + encodeURIComponent('CNT CT') + '&vendor=KW&pallet=3');
  const cc = (pv1.counts || [])[0] || {};
  check('saved once (sent twice): opened, our record 9 → counted 8 (−1) with the sum typed (2×3+2), by who; no count → refused',
    c1.ok && c1.diff === -1 && (pv0.counts || []).length === 0 && (pv1.counts || []).length === 1 && cc.opened === true && cc.expected === 9 && cc.counted === 8 && cc.diff === -1 && cc.by === 'TS' && cc.how === '2×3+2' && bad.ok === false,
    { c1, c2, bad, counts: pv1.counts });
  // Owner (2026-10-10, photo): "1 entry saved on this phone … Start count … Not in History — sending again · tries: 34".
  // It was saved the first time; the outbox check only looked in inventory_log, so the phone kept sending it.
  const oc = await post('/inventory/outbox/check', { ids: ['cnt-test-1'] });
  sq.prepare("INSERT INTO processed_requests (request_id, endpoint, created_at, response_json) VALUES (?,?,?,?)").run('cnt-old-1', 'inventory/containers/pallet-count', new Date().toISOString(), JSON.stringify({ ok: true, expected: 17, counted: 17, diff: 0 }));
  const oc2 = await post('/inventory/outbox/check', { ids: ['cnt-old-1'] });
  check('outbox check: a start count is found on record ("saved", not "Not in History — sending again"), also one saved before the fix (stuck on a phone)',
    c1.countId > 0 && oc.results && oc.results['cnt-test-1'].state === 'saved' && oc2.results && oc2.results['cnt-old-1'].state === 'saved', { c1, oc, oc2 });
  check('…History → the pallet shows it ("🧮 Box count before starting")', det.ok && (det.counts || []).length === 1 && det.counts[0].counted === 8 && /🧮 Box count before starting/.test(ih), det.counts);
  const ml1 = JSON.stringify(sq.prepare('SELECT SUM(cases) c FROM master_list').get()), lg1 = sq.prepare('SELECT COUNT(*) n FROM inventory_log').get().n;
  check('…inventory does not change (SKU Mgr total ' + ml0 + ' → ' + ml1 + ', entries ' + lg0 + ' → ' + lg1 + ')', ml0 === ml1 && lg0 === lg1, { ml0, ml1, lg0, lg1 });

  // The screen: asked at the top until answered, a move (shelf scan) waits for it; asked once per person per pallet.
  const src = ih.slice(ih.indexOf('  xfrGo.startDone = {}; xfrGo.startCk = null;'), ih.indexOf('  function xfrGoLineWarn(l) {'));
  const W0 = {}, posts = [], flashes = [];
  const xfrGo = { focus: { title: 'CNT CT', vendor: 'KW', pallet: '3' }, lines: [{ left: 6, moved: 0 }, { left: 3, moved: 0 }], counts: [] };
  const fn = new Function('window', 'xfrGo', 'INV_CRED_USER', 'g', 'xfrE', 'xfrN', 'invPost', 'invFlash', 'W', 'xfrGoRender', 'xfrGoBox', 'xfrCalcTotal', 'xfrCalcPress',
    src + '; return { needed: xfrStartNeeded, panel: xfrStartPanel, line: xfrStartLine };');
  const cs0 = ih.slice(ih.indexOf('  function xfrCalcTotal(expr) {'), ih.indexOf('  // ⚠ The box\'s UPC is not for this part #'));
  const C = new Function('window', cs0 + '; return { total: xfrCalcTotal, press: xfrCalcPress };')({});
  const H = fn(W0, xfrGo, { displayName: 'TS' }, () => null, String, v => String(v), (u, o) => { posts.push([u, JSON.parse(o.body)]); return Promise.resolve({ json: () => ({ ok: true }) }); },
    (m, t) => flashes.push(t), 'W', () => {}, () => {}, C.total, C.press);
  const need0 = H.needed(), p0 = H.panel();
  W0.xfrStartStep('open'); W0.xfrStartOpened(false); const p1 = H.panel();
  W0.xfrStartSave(9);
  const need1 = H.needed(), ln = H.line();
  xfrGo.startDone = {}; const need2 = H.needed(); // same person, same pallet, page reloaded → not asked again within 12 h
  check('asked at the top: ▶ Start → opened? → "Our record: 9 box(es)" with the 🧮 calculator right there and ✅ Correct — 9; saved (not opened, 9 = 9), not asked again',
    need0 && /▶ Start working on Pallet 3/.test(p0) && /Our record: <b[^>]*>9<\/b>/.test(p1) && /✅ Correct — 9/.test(p1) && /🧮 Count: e\.g\. 4 layers × 6 boxes \+ 3 on top/.test(p1)
      && /xfrStartCalcKey\('×'\)/.test(p1) && /xfrStartCalcKey\('='\)/.test(p1) && !/Save my count/.test(p1)
      && posts.length === 1 && posts[0][1].expected === 9 && posts[0][1].counted === 9 && posts[0][1].opened === false && !need1 && !need2 && /✓ matched our record/.test(ln), { need0, need1, need2, posts });
  // Owner (2026-10-10): "correct or not, as soon as how many cases we have comes out, a calculation, so they can do the math".
  xfrGo.counts = [{ at: new Date(Date.now() - 13 * 3600000).toISOString(), by: 'TS', counted: 9, expected: 9, diff: 0 }]; // next day → asked again
  const need3 = H.needed(); H.panel(); W0.xfrStartStep('open'); W0.xfrStartOpened(true);
  ['2', '×', '3', '+', '+', '2'].forEach(k => W0.xfrStartCalcKey(k));
  const p2 = H.panel(); W0.xfrStartCalcSave();
  check('…count in parts on the spot: 2 × 3 + 2 → "= 8", "-1 vs our record 9" in red, 💾 Save my count — 8 → saved 8 vs 9 with the sum, shown in red; asked again after 12 h',
    need3 && /2 × 3 \+ 2/.test(p2) && /= 8<\/div>/.test(p2) && /-1 vs our record 9/.test(p2) && /💾 Save my count — 8/.test(p2)
      && posts.length === 2 && posts[1][1].counted === 8 && posts[1][1].expected === 9 && posts[1][1].opened === true && posts[1][1].how === '2×3+2'
      && /our record 9 \(-1\)/.test(H.line()) && /8 box\(es\) \(2×3\+2\)/.test(H.line()), { posts, line: H.line() });
  xfrGo.startDone = {}; xfrGo.counts = []; H.panel(); W0.xfrStartStep('open'); W0.xfrStartOpened(true);
  ['4', '×', '2', '+', '1'].forEach(k => W0.xfrStartCalcKey(k));
  const p3 = H.panel(); const onC = (p3.match(/onclick="(xfrStartCorrect\(\))"/) || [])[1]; W0.xfrStartCorrect();
  check('…4 × 2 + 1 = 9 → "✓ Matches our record (9)", no Save my count; ✅ Correct saves 9 with the sum',
    /✓ Matches our record \(9\)/.test(p3) && !/Save my count/.test(p3) && onC === 'xfrStartCorrect()' && !/onclick="[^"]*xfrGo\./.test(p1 + p2 + p3) && posts.length === 3 && posts[2][1].counted === 9 && posts[2][1].how === '4×2+1', posts[2]);
  check('…a move waits for it (shelf scan → "First confirm the boxes on this pallet"); the panel sits right under the pallet title',
    /window\.xfrGoMove = function\(toLoc\) \{\n    var sel = xfrGo\.sel; if \(!sel\) return;\n    if \(xfrStartNeeded\(\)\) \{ invFlash\('⬆ First confirm the boxes on this pallet/.test(ih)
      && /\+ xfrE\(f\.title\) \+ '<\/span><\/div>'\n      \+ \(xfrStartNeeded\(\) \? xfrStartPanel\(\) : ''\)/.test(ih), null);
  // Owner (2026-10-10): a calculator in that step — count the pallet in parts (layers × boxes + extra on top).
  const cs = ih.slice(ih.indexOf('  function xfrCalcTotal(expr) {'), ih.indexOf('  window.xfrCalcTotal = xfrCalcTotal;'));
  const calc = new Function(cs + '; return xfrCalcTotal;')();
  const cases = [['4×6+3', 27], ['27', 27], ['0', 0], ['5×4×2', 40], ['30−2', 28], ['2+3×4', 14], ['10−3−2', 5], ['4×6+', null], ['×3', null], ['', null], ['4××6', null], ['2.5×2', 5]];
  const got = cases.map(([e]) => calc(e));
  check('calculator: 4×6+3 = 27, 5×4×2 = 40, 30−2 = 28, 2+3×4 = 14 (× first), 10−3−2 = 5; an unfinished sum (4×6+, ×3, empty) is not a total',
    cases.every(([e, v], i) => got[i] === v), cases.map(([e, v], i) => e + ' → ' + got[i] + (got[i] === v ? '' : ' ✗ want ' + v)));
  const P = keys => keys.reduce((v, k) => C.press(v, k), '');
  check('…keys: 4 × 6 + + 3 → 4×6+3 (a 2nd + replaces the 1st), "=" → 27, ⌫ / C, no sign first, a leading 0 replaced',
    P(['4', '×', '6', '+', '+', '3']) === '4×6+3' && P(['4', '×', '6', '+', '3', '=']) === '27' && P(['1', '2', '⌫']) === '1' && P(['5', 'C']) === '' && P(['×', '3']) === '3' && P(['0', '7']) === '7', null);
  check('…the normal number pad (Moving how many …) is unchanged',
    /\['1','2','3','4','5','6','7','8','9','\.','0','⌫'\]/.test(ih) && !/xfrKeypadCalc/.test(ih)
      && /window\.xfrKeypad = function\(title, start, cb, zeroOk\) \{ xfrKp = \{ title: title, v: start \? String\(start\) : '', cb: cb, zeroOk: !!zeroOk \}; xfrKpDraw\(\); \};/.test(ih), null);
  sq.exec("DELETE FROM reorder_pallet WHERE title='CNT CT'; DELETE FROM pallet_count WHERE title='CNT CT'");
}

// Owner (2026-10-10): "Warehouse Lookup → Stock Levels: is it accurate right now? Match SKU Mgr (what we have now), the
