// Owner (2026-10-16): "as long as one is not saved, no matter who is using the phone, as soon as there is WiFi the system
// updates it — our part-time worker comes once a month". Every person's entries saved on a phone are sent by whoever is
// signed in; each is still recorded as the person who made it.
console.log('\n📶 Phone outbox: sent whoever is signed in, recorded as the person who made it');
{
  const { readFileSync } = await import('node:fs');
  const ih = readFileSync(fileURLToPath(new URL('../inventory.html', import.meta.url)), 'utf8');
  const tsId = sq.prepare("SELECT id FROM cred_users WHERE username = 'tester'").get().id;
  const pkHd = { 'X-Cred-Token': pk.token, 'Content-Type': 'application/json' };
  const send = async b => (await call('/inventory/containers/pallet-count', { method: 'POST', headers: pkHd, body: JSON.stringify(b) })).json();
  const base = { title: 'OBW CT', vendor: 'KW', pallet: '1', opened: true, expected: 5, counted: 5 };
  const r1 = await send({ ...base, _outbox: true, _byUserId: tsId, _requestId: 'obw-1' });   // TS saved it, PK's sign-in sends it
  const r2 = await send({ ...base, _outbox: true, _requestId: 'obw-2' });                    // PK's own
  const r3 = await send({ ...base, _outbox: true, _byUserId: 999999, _requestId: 'obw-3' }); // unknown person → the sender
  const r4 = await send({ ...base, _byUserId: tsId, _requestId: 'obw-4' });                  // not from the outbox → never swapped
  const by = sq.prepare("SELECT by_user FROM pallet_count WHERE title = 'OBW CT' ORDER BY id").all().map(r => r.by_user);
  check('TS\'s saved entry sent later by PK\'s sign-in is recorded as TS; PK\'s own as PK; an unknown person or a non-outbox request stays the sender',
    r1.ok && r2.ok && r3.ok && r4.ok && JSON.stringify(by) === '["TS","PK","PK","PK"]', by);
  sq.exec("DELETE FROM pallet_count WHERE title = 'OBW CT'");
  // The phone: every person's list is read and sent; each entry carries who made it.
  const store = {}, ls = { get length() { return Object.keys(store).length; }, key: i => Object.keys(store)[i], getItem: k => (k in store ? store[k] : null), setItem: (k, v) => { store[k] = String(v); } };
  const src = ih.slice(ih.indexOf('function invObKey() {'), ih.indexOf('function invObNewId() {'));
  const O = new Function('localStorage', 'INV_CRED_USER', 'invObRender', 'invObSchedule', src + '; return { read: invObRead, write: invObWrite, patch: invObPatch, owner: invObOwnerId, key: invObKey };')(
    ls, { userId: 2, displayName: 'PK' }, () => {}, () => {});
  store['xf_inv_outbox_1'] = JSON.stringify([{ id: 'm1', state: 'waiting', body: { notes: '[AUDIT] x' }, by: 'Maria' }]);   // part-timer, saved last month
  store['xf_inv_outbox_2'] = JSON.stringify([{ id: 'p1', state: 'waiting', body: {}, by: 'PK' }]);
  const all = O.read().map(x => x.id).sort();
  O.patch('m1', y => { y.state = 'sent'; });
  const m1 = JSON.parse(store['xf_inv_outbox_1'])[0], p1 = JSON.parse(store['xf_inv_outbox_2'])[0];
  check('signed in as PK: Maria\'s waiting entry (saved under her name on this phone) is read and sent too, kept in her own list; it is sent as hers (_byUserId 1)',
    JSON.stringify(all) === '["m1","p1"]' && m1.state === 'sent' && p1.state === 'waiting' && O.owner({ _k: 'xf_inv_outbox_1', body: {} }) === 1
      && /body\._byUserId = INV_CRED_USER\.userId;/.test(ih) && /sendBody = Object\.assign\(\{\}, sendBody, \{ _byUserId: invObOwnerId\(ent\) \}\)/.test(ih), { all, m1, p1 });
}

// Owner (2026-10-16): "Auto Label — Mon–Fri stop the 30-min wait at 3:30 pm, wait 3 min; from 4 pm print as soon as an order
// comes in; Saturday from 12:30 pm 3 min, from 1 pm instant". 🗓 Auto print schedule says it in plain words.
console.log('\n🗓 Auto Label schedule: Mon–Fri 3:30 pm 3 min → 4 pm no wait; Sat 12:30 pm 3 min → 1 pm no wait');
{
  const { readFileSync } = await import('node:fs');
  const ph = readFileSync(fileURLToPath(new URL('../packship.html', import.meta.url)), 'utf8');
  const grab = re => (ph.match(re) || [''])[0];
  const src = [grab(/function _psAlClock\(hm\) \{[\s\S]*?\n\}/), grab(/var _PS_DAYN = [\s\S]*?\nfunction _psAlSchedRender/).replace(/\nfunction _psAlSchedRender$/, '')].join('\n');
  const html = new Function('var _psAlEsc = function(v){return String(v);};' + src + '; return _psAlSchedHtml;')()({ waitMinutes: 30, noWaitMinutes: 3,
    noWaitTimes: 'Mon-Fri 15:30-16:00=3; Mon-Fri 16:00-24:00=0; Sat 12:30-13:00=3; Sat 13:00-24:00=0', pauseTimes: 'Mon-Fri 16:30-17:30; Sat 13:45-15:00; Mon-Sun 20:30-24:00; Mon-Sun 0:00-0:05',
    scanFormOn: true, scanFormTimes: 'Mon-Fri 16:30, 20:45; Sat 13:45, 20:45; Sun 20:45' });
  const txt = html.replace(/<\/tr>/g, '\n').replace(/<div style="font-weight:800">/g, '\n== ').replace(/<[^>]+>/g, ' ').replace(/[ ]+/g, ' ');
  const part = name => (txt.split('== ' + name)[1] || '').split('==')[0];
  const mf = part('Mon–Fri'), sa = part('Saturday'), su = part('Sunday');
  check('Mon–Fri: 3:30 pm "No 30-min wait — new orders wait 3 min", 4:00 pm "⚡ No wait — prints as soon as it comes in" (no "back to the 30-min wait" in between); Sat 12:30 pm 3 min, 1:00 pm ⚡; Sunday unchanged',
    /3:30 pm ⏩ No 30-min wait — new orders wait 3 min/.test(mf) && /4:00 pm ⚡ No wait — an order prints as soon as it comes in/.test(mf) && !/4:00 pm[^\n]*Back to the/.test(mf)
    && /12:30 pm ⏩ No 30-min wait — new orders wait 3 min/.test(sa) && /1:00 pm ⚡ No wait/.test(sa) && !/⏩|⚡/.test(su), { mf, sa, su });
}

// Owner (2026-10-16): "Print Log — nothing got picked up after 2:13 pm today, I see the scanner works, but no record and
// the number stayed the same". A Print Log scan was sent once and dropped silently when that failed (WiFi, signed out).
// Now it is saved on the station computer first and sent again until the server has it (never twice, at its real time),
// and the screen says in red when scans are not sent or the scanner is not typing into the page.
console.log('\n🖨 Print Log: scans saved on the station until recorded, never twice, real scan time; red warning');
{
  const { readFileSync } = await import('node:fs');
  const ph = readFileSync(fileURLToPath(new URL('../packship.html', import.meta.url)), 'utf8');
  const T = '9400100000000000000777';
  const at = new Date(Date.now() - 30 * 60000).toISOString();
  const a1 = await post('/ship/print-log', { tracking: T, _requestId: 'pl-t-1', at });
  const a2 = await post('/ship/print-log', { tracking: T, _requestId: 'pl-t-1', at });   // sent again (reply lost)
  const rows = sq.prepare('SELECT date, timestamp FROM ship_print_log WHERE tracking = ?').all(T);
  const nyDate = new Date(at).toLocaleDateString('en-CA', { timeZone: 'America/New_York' });
  const fut = await post('/ship/print-log', { tracking: '9400100000000000000778', _requestId: 'pl-t-2', at: new Date(Date.now() + 3 * 3600e3).toISOString() });
  const futRow = sq.prepare('SELECT timestamp FROM ship_print_log WHERE tracking = ?').get('9400100000000000000778') || {};
  check('a scan sent twice (same id) is recorded ONCE, at the time it was really scanned (30 min ago, its New York day); a time in the future is never used',
    a1.ok && a2.ok && rows.length === 1 && rows[0].timestamp === at && rows[0].date === nyDate && fut.ok && Math.abs(Date.parse(futRow.timestamp) - Date.now()) < 60000, { a1, a2, rows, futRow });
  sq.exec("DELETE FROM ship_print_log WHERE tracking IN ('9400100000000000000777','9400100000000000000778')");
  // The station page
  const grab = (s, e) => { const i = ph.indexOf(s); return ph.slice(i, ph.indexOf(e, i)); };
  const src = grab('var PS_PL_QUEUE_KEY', "setInterval(function() { if (psPlQueueRead().length) psPlFlush(); }, 15000);");
  const store = {}, el = { innerHTML: '', style: {} }; let mode = 'down'; const sent = [];
  const fakeFetch = async (u, o) => { sent.push(JSON.parse(o.body)); if (mode === 'down') throw new Error('net');
    if (mode === '401') return { status: 401, json: async () => ({ error: 'Unauthorized' }) };
    return { status: 200, json: async () => ({ ok: true }) }; };
  const P = new Function('window', 'localStorage', 'document', 'fetch', 'PS_WORKER', 'psCredToken', 'psPlScans', 'psPlRenderList', 'psFetchPrintDupeCount', 'psFmtTime',
    src + '; return { add: psPlQueueAdd, read: psPlQueueRead, flush: () => window.psPlFlush(), warn: psPlWarnRender };')(
    {}, { getItem: k => store[k] || null, setItem: (k, v) => { store[k] = String(v); } }, { getElementById: () => el }, fakeFetch, 'W', 't', [], () => {}, () => {}, String);
  P.add({ id: 'q1', tracking: T, at }); await new Promise(r => setTimeout(r, 5));
  const w1 = el.innerHTML, n1 = P.read().length;
  mode = '401'; await P.flush(); const w2 = el.innerHTML, n2 = P.read().length;
  mode = 'ok'; await P.flush(); const n3 = P.read().length, w3 = el.style.display;
  check('station: no WiFi → kept on the computer, red "1 scan saved on this computer, NOT in the Print Log yet — no WiFi"; signed out → kept, "SIGNED OUT — sign in again"; back → sent (same id + scan time) and gone',
    n1 === 1 && /1 scan saved on this computer, NOT in the Print Log yet — no WiFi/.test(w1) && n2 === 1 && /SIGNED OUT — sign in again/.test(w2) && n3 === 0 && w3 === 'none'
      && sent.every(b => b._requestId === 'q1' && b.at === at), { w1, w2, n1, n2, n3, sent: sent.length });
  check('…every Print Log scan goes through that list (never a single send that can be lost); the window-not-in-front warning; unsent scans stay on the list after a reload',
    /psPlQueueAdd\(\{ id: _psPlNewId\(\), tracking: clean, at: ts \}, entry\);/.test(ph) && !/fetch\(PS_WORKER \+ '\/ship\/print-log', \{\n    method: 'POST'/.test(ph)
      && /The scanner is NOT typing into the Print Log/.test(ph) && /var nf = !document\.hasFocus\(\);/.test(ph) && /psPlQueueRead\(\)\.forEach\(function\(q\) \{ if \(!psPlScans\.some/.test(ph), null);
}

