  const n2 = await post('/inventory/log', { type: 'OUT', partNum: '711-1-11=5XX', sku: '711-1-11', location: L, cases: 2, initials: 'MK', notes: '[AUDIT] [NONE FOUND] System: 2 → Actual: 0 (diff: -2.0) (📋 Recount)', masterId: ids['711-1-11=5XX'] });
