  const fba = L.awdLabelSkus([{ y: 10, text: 'FBA19QRYL9THU000109' }, { y: 20, text: 'Single SKU' }, { y: 22, text: '30-3-6=2X-' }, { y: 24, text: 'Qty 10' }]);
  const mixed = L.awdLabelSkus([{ y: 10, text: 'Mixed SKUs' }, { y: 20, text: 'FNSKU: X00ABC' }]);
